int getRandom(int min, int max) {
    double scaled = (double)rand()/RAND_MAX; 
    return (max-min+1)*scaled + min;
}

// Function to generate monthly sales
int getMonthlySales(){
   return getRandom(0, 100000);
}

void calculateQuarterlySales() {
    int quarterSum[4] = {0}; // Array for the sum of each quarter
    int current_month = 0;

    srand((unsigned int)time(NULL)); // Seed random number generator

    for(int i=1;i<=12;i++){
        int salesForMonth = getMonthlySales(); 
        quarterSum[current_month] += salesForMonth;

        printf("Month %d Sales: $%d\n", i, salesForMonth); // Print monthly sales

        if(i % 3 == 0){ // Every third month end of the quarter.
            current_month++;
        }
    }

    for(int j=0;j<4;j++) {
       printf("Quarter %d Sales: $%d\n", j+1, quarterSum[j]); // Print quarterly sales
    }
}

int main() {
