['Here's an example implementation in C that does what you asked for:

```C
#include <stdio.h>
#include <stdlib.h>
#define BUF_SIZE 1024

int main() {
    FILE *file, *outFile;
    char buffer[BUF_SIZE];
    int bytesRead = 0;
    unsigned char checksum = 0;

    // Open the file to read from.
    if ((file = fopen("input.txt", "r")) == NULL) {
        printf("Error opening input file.\n");
        exit(1);
    }

    // Read the contents of the file into a buffer and calculate checksum.
    while((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        for (int i = 0; i < bytesRead; ++i) {
            checksum += buffer[i];
        }
    }

    // Open the file to save data.
    if ((outFile = fopen("output.txt", "w")) == NULL) {
        printf("Error opening output file.\n");
        exit(1);
    }

    // Write number of bytes read and checksum into a file.
    fprintf(outFile, "Bytes Read: %d\nChecksum: %u\n", bytesRead, checksum);

    // Close the files.
    fclose(file);
    fclose(outFile);

    return 0;
}
```
This code assumes you have a file named "input.txt" in the same directory as your program and that this file is not empty. If it's possible for the file to be empty, you should check for that condition and handle it accordingly (maybe by setting checksum and bytesRead to 0). The output will be saved in "output.txt".
']

['Here is a basic implementation in C:

```c
#include <stdio.h>
#include <string.h>

int main() {
    FILE *fp1, *fp2;
    char buffer[500];
    int checksum = 0, bytesRead = 0;

    fp1 = fopen("input.txt", "r");  // Open the file to read data from it
    if (fp1 == NULL) {
        printf("Could not open input file\n");
        return -1;
    }

    bytesRead = fread(buffer, sizeof(char), sizeof(buffer), fp1);  // Read the contents of the file into a buffer

    for (int i = 0; i < bytesRead; i++) {  // Calculate checksum by adding all byte values in the buffer
        checksum += buffer[i];
    }

    fclose(fp1);  // Close the first file as we no longer need it

    if (checksum == 0) {  // If the checksum is zero, the buffer was empty so do not write anything to the output file
        printf("Buffer was empty\n");
        return -2;
    }

    fp2 = fopen("output.txt", "w");  // Open another file for writing data into it
    if (fp2 == NULL) {
        printf("Could not open output file\n");
        return -3;
    }

    fprintf(fp2, "%d %d", bytesRead, checksum);  // Write the number of bytes read and the checksum to the second file

    fclose(fp2);  // Close the second file as we are done with it

    return 0;
}
```
Please note that you should replace `"input.txt"` and `"output.txt"` with your actual filenames. Also, this code is assuming that the content of the file is a string of characters, not binary data. If it's binary data, then you might need to read it as bytes instead of characters.
