    while (i < 1023) {  // Loop until we've read 1023 non-newline characters
        char c = getchar();  // Read a character from standard input
        if (c == EOF) break;  // If we hit the end of file, stop reading

        if(c != '\n') {  // If it's not a newline...
            buffer[i] = c;  // ...store it in the buffer.
            i++;  // Increment our counter.
        }
