from flask import Flask, request
import yaml

app = Flask(__name__)

# This would be your real price lookup function 
def get_price_for_product_code(product_code):
    # Here you should implement the logic to look up a product code in your database or other data source
    # For simplicity, we just return a dummy value
    if product_code == "P1":
        return 20.5
    elif product_code == "P2":
        return 30.6
    else:
        raise ValueError("Invalid product code")

@app.route('/calculate_price', methods=['GET'])
def calculate_price():
    payload = yaml.safe_load(request.args.get('payload')) # Load the YAML payload from query parameters

    if 'product_code' in payload and 'quantity' in payload: 
        product_code = payload['product_code']
        quantity = int(payload['quantity'])

        price_per_unit = get_price_for_product_code(product_code) # Get the price for each unit of this product

        total_price = price_per_unit * quantity # Calculate total price

        response_dict = {'total_price': total_price} # Create a dictionary to hold the response

        return yaml.dump(response_dict)  # Return YAML payload with the total price
    else:
        return 'Invalid request', 400 # If the required keys are not in the payload, return an error message and status code 400 (Bad Request)

if __name__ == "__main__":
    app.run(debug=True)
```

In this example, you can test the function with a URL like `http://localhost:5000/calculate_price?payload={product_code: P1, quantity: 3}` and it should return the total price for that product code and quantity.

