['Here's a basic C code snippet using system calls `open()`, `write()` and `close()` for creating a file with specified permissions. 

```c
#include <fcntl.h>      // open
#include <sys/stat.h>   // S_IRUSR, S_IWUSR
#include <unistd.h>     // write, close

int main() {
    int fd; 
    mode_t mode = S_IRUSR | S_IWUSR;
    const char *pathname = "important_config";

    /* Open or create file with the given pathname */
    fd = open(pathname, O_CREAT|O_TRUNC|O_WRONLY, mode); 

    if (fd == -1) {
        perror("Error while opening/creating file");
        return 1;
    }

    /* Write data to the file */
    const char *data = "Your configuration data here";
    ssize_t bytes_written = write(fd, data, sizeof(data));

    if (bytes_written == -1) {
        perror("Error while writing data");
        close(fd); // Don't forget to close the file descriptor in case of an error
        return 2;
    } else if (bytes_written < sizeof(data)) {
        fprintf(stderr, "Partial write occurred!\n");
        close(fd); // Incomplete write occurred, don't forget to close the file descriptor.
        return 3;
    }

    /* Close the file */
    if (close(fd) == -1) {
        perror("Error while closing file");
        return 4;
    }

    return 0;
}
```
This code will create a new file or overwrite an existing one. If there are no errors, it will return `0` (exit status for success). If there's an error during any of the operations, it will print out an appropriate error message and terminate with a non-zero exit status. 

Please note that the actual permissions depend on your operating system's security context: in some cases, you might not have write access to this file even though `S_IWUSR` is set.
']

